static const char *fmtr_lookup(const char *s, int l)
{
    if (!lang_ok(l)) return 0;
    for (unsigned i = 0; i < sizeof FMTR / sizeof FMTR[0]; i++) if (!strcmp(FMTR[i][0], s)) return FMTR[i][1 + l];
    return 0;
}
